def get_diamond_points(r, c):
    # Diamond pattern: 4s on top/middle/bottom edges, 2s at bottom corners
    points = {
        (r-1, c-1): 4, (r-1, c+1): 4,
        (r, c-1): 4,   (r, c): 4,   (r, c+1): 4,
        (r+1, c-1): 2, (r+1, c+1): 2
    }
    return points

def add_diamond(grid, r, c):
    for (pr, pc), val in get_diamond_points(r, c).items():
        if pr >= 0 and pr < 12 and pc >= 0 and pc < 8:
            grid[pr][pc] = val

add_diamond(output, 0, 4)
