import json
import requests

# Demo analysis: 4 at (4,2) → points at (3,0), (3,4), (4,1), (4,3), (5,2)
# Pattern: For each 4 at (r,c), output has 4s at:
# (r-1, c-2), (r-1, c+2), (r, c-1), (r, c+1), (r+1, c)

# Test 12x8 grid: 4s at (0,4), (1,0), (6,1), bar at row 3
# Let me recalculate more explicitly
output = [[0] * 8 for _ in range(12)]

# Bar
for c in range(8):
    output[3][c] = 2

# Apply transformation to each 4
for sr, sc in [(0, 4), (1, 0), (6, 1)]:
    # Top: (sr-1, sc-2), (sr-1, sc+2)
    if sr - 1 >= 0 and sc - 2 >= 0:
        output[sr - 1][sc - 2] = 4
    if sr - 1 >= 0 and sc + 2 < 8:
        output[sr - 1][sc + 2] = 4
    # Mid: (sr, sc-1), (sr, sc+1)
    if sc - 1 >= 0:
        output[sr][sc - 1] = 4
    if sc + 1 < 8:
        output[sr][sc + 1] = 4
    # Bottom: (sr+1, sc)
    if sr + 1 < 12:
        output[sr + 1][sc] = 4

# Let me print out each contribution for verification
print("Output contributions:")
for sr, sc in [(0, 4), (1, 0), (6, 1)]:
    contribs = []
    if sr - 1 >= 0 and sc - 2 >= 0: contribs.append(f"({sr-1},{sc-2})")
    if sr - 1 >= 0 and sc + 2 < 8: contribs.append(f"({sr-1},{sc+2})")
    if sc - 1 >= 0: contribs.append(f"({sr},{sc-1})")
    if sc + 1 < 8: contribs.append(f"({sr},{sc+1})")
    if sr + 1 < 12: contribs.append(f"({sr+1},{sc})")
    print(f"4 at ({sr},{sc}) → {contribs}")

print("\nFinal row-by-row:")
for r in range(12):
    row_str = ''.join(['4' if c == 4 else '·' for c in output[r]]) if r != 3 else '─' * 8
    print(f"Row {r}: {row_str}")

print("\nJSON:", json.dumps({"action": "submit", "grid": output}))

