import json

# Try with threshold >= 1 (just union of all crosses)
output = [[0] * 8 for _ in range(12)]
influence = [[0] * 8 for _ in range(12)]

def mark_cross(r, c, count):
    for dr, dc in [(-1,0), (1,0), (0,-1), (0,1), (0,0)]:
        if 0 <= r+dr < 12 and 0 <= c+dc < 8:
            count[r+dr][c+dc] += 1
            output[r+dr][c+dc] = not output[r+dr][c+dc]

for sr, sc in [(0, 4), (1, 0), (6, 1)]:
    mark_cross(sr, sc, influence)

print("Crosses (union pattern):")
for r in range(12):
    string_list = []
    for c in range(8):
        if r == 3:
            string_list.append(str(2))
        elif output[r][c] or influence[r][c] > 0:
            string_list.append('4')
        else:
            string_list.append('·')
    print(f"Row {r}: {''.join(string_list)}")

